//
// TO ADD A QUESTION: copy any entry below, edit it, and keep the comma.
//   { Testament::Old or Testament::New,
//     "Question text?",
//     { "Choice A", "Choice B", "Choice C", "Choice D" },
//     index_of_correct_choice },   // 0 = first choice, 1 = second, ...
